def find_closest_elements(numbers: List[float]) -> Tuple[float, float]:
    if len(numbers) < 2:
        raise ValueError("List must contain at least two elements")

    differences = [(abs(numbers[i] - numbers[j]), numbers[i], numbers[j]) for i in range(len(numbers)) for j in range(i+1, len(numbers))]
    differences.sort(key=lambda x: x[0])

    for i in range(len(differences)):
        if differences[i][1] != differences[i][2]:
            return (min(differences[i][1], differences[i][2]), max(differences[i][1], differences[i][2]))

    return (differences[0][1], differences[0][2])

